/* Additional grammar rules for the Grammatik-Regel-Trainer (Task 52) — closes the gaps found in the grammar review
   (Goethe/telc A1–B1): each rule = { id, level, title, category, color, summary, formula, tableHTML, examples, bank }.
   bank = practice questions {p, en, o:[correct, …3 wrong], exp}; the page turns them into drills + an endless
   generator. Examples and explanations written with AI assistance and checked against standard grammar references. */
(function () {
  const T = rows => `<table class="de-table">${rows.map((r, i) => `<tr>${r.map(c => i ? `<td>${c}</td>` : `<th>${c}</th>`).join('')}</tr>`).join('')}</table>`;
  const clock = (h, m, label) => {                       // analog clock picture for the time rule
    const a = (m / 60) * 2 * Math.PI, b = ((h % 12) + m / 60) / 12 * 2 * Math.PI;
    const mx = 30 + 20 * Math.sin(a), my = 30 - 20 * Math.cos(a), hx = 30 + 13 * Math.sin(b), hy = 30 - 13 * Math.cos(b);
    const ticks = Array.from({ length: 12 }, (_, i) => { const t = i / 12 * 2 * Math.PI; return `<line x1="${30 + 23 * Math.sin(t)}" y1="${30 - 23 * Math.cos(t)}" x2="${30 + 26 * Math.sin(t)}" y2="${30 - 26 * Math.cos(t)}" stroke="currentColor" stroke-width="1.5"/>`; }).join('');
    return `<div class="prep-tile" style="text-align:center;"><svg viewBox="0 0 60 60" width="84" height="84" style="justify-self:center; color:#2563eb;" role="img" aria-label="${label}"><circle cx="30" cy="30" r="27" fill="none" stroke="currentColor" stroke-width="2.5"/>${ticks}<line x1="30" y1="30" x2="${hx}" y2="${hy}" stroke="#1e293b" stroke-width="3.5" stroke-linecap="round"/><line x1="30" y1="30" x2="${mx}" y2="${my}" stroke="#e11d48" stroke-width="2.2" stroke-linecap="round"/><circle cx="30" cy="30" r="2" fill="#1e293b"/></svg><div class="prep-w" style="font-size:16px;">${label}</div></div>`;
  };
  const bars = (items) => `<div class="prep-grid" style="grid-template-columns:repeat(3, minmax(90px, 1fr)); align-items:end;">${items.map(([h, t, s]) => `<div class="prep-tile" style="text-align:center;"><svg viewBox="0 0 40 70" width="46" height="80" style="justify-self:center;"><rect x="8" y="${70 - h}" width="24" height="${h}" rx="3" fill="#2563eb"/></svg><div class="prep-w" style="font-size:15px;">${t}</div><div class="prep-en">${s}</div></div>`).join('')}</div>`;

  window.DC_GRAMMAR_EXTRA = [
  /* ============================ A1 ============================ */
  { id: 'a1_praesens', level: 'A1', category: 'Verbs', color: 'var(--red)',
    title: 'Präsens: Verb-Endungen, Vokalwechsel & du / Sie (Present Tense)',
    summary: 'Every German verb changes its ending for the person — like Tamil (போகிறேன் / போகிறாய் / போகிறார்). Learn the 6 endings once and they work for almost every verb.',
    formula: '• Stem + ending: ich -e · du -st · er/sie/es -t · wir -en · ihr -t · sie/Sie -en\n• Stem ends in -t/-d/-chn/-ffn: extra -e- → du arbeitest, er arbeitet, ihr findet\n• Stem ends in -s/-ß/-z: du only adds -t → du heißt, du tanzt\n• Strong verbs change the vowel ONLY in du + er/sie/es: e→i (sprechen → du sprichst), e→ie (lesen → du liest), a→ä (fahren → du fährst), au→äu (laufen → du läufst)\n• du = friends, family, children (Tamil நீ) · Sie = strangers, work, officials (Tamil நீங்கள்) — Sie is always capitalised and uses the -en form',
    tableHTML: T([['Person', 'lernen', 'arbeiten', 'sprechen (e→i)', 'fahren (a→ä)', 'sein', 'haben'],
      ['ich', 'lern<b>e</b>', 'arbeit<b>e</b>', 'sprech<b>e</b>', 'fahr<b>e</b>', '<b>bin</b>', 'hab<b>e</b>'],
      ['du', 'lern<b>st</b>', 'arbeit<b>est</b>', 'spr<b>i</b>ch<b>st</b>', 'f<b>ä</b>hr<b>st</b>', '<b>bist</b>', 'ha<b>st</b>'],
      ['er / sie / es', 'lern<b>t</b>', 'arbeit<b>et</b>', 'spr<b>i</b>ch<b>t</b>', 'f<b>ä</b>hr<b>t</b>', '<b>ist</b>', 'ha<b>t</b>'],
      ['wir', 'lern<b>en</b>', 'arbeit<b>en</b>', 'sprech<b>en</b>', 'fahr<b>en</b>', '<b>sind</b>', 'hab<b>en</b>'],
      ['ihr', 'lern<b>t</b>', 'arbeit<b>et</b>', 'sprech<b>t</b>', 'fahr<b>t</b>', '<b>seid</b>', 'hab<b>t</b>'],
      ['sie / Sie', 'lern<b>en</b>', 'arbeit<b>en</b>', 'sprech<b>en</b>', 'fahr<b>en</b>', '<b>sind</b>', 'hab<b>en</b>']]),
    examples: [{ de: 'Ich lerne Deutsch, und du lernst Englisch.', en: 'I learn German and you learn English.' },
      { de: 'Fährst du morgen nach Berlin?', en: 'Are you driving to Berlin tomorrow? (a → ä in the du-form)' },
      { de: 'Woher kommen Sie, Frau Kumar?', en: 'Where are you from, Mrs Kumar? (formal Sie)' }],
    bank: [
      { p: 'Du ___ sehr gut Deutsch. (sprechen)', en: 'You speak German very well.', o: ['sprichst', 'sprechst', 'spricht', 'sprecht'], exp: 'sprechen changes e → i in the du- and er-form: du sprichst.' },
      { p: 'Er ___ jeden Tag mit dem Bus. (fahren)', en: 'He goes by bus every day.', o: ['fährt', 'fahrt', 'fährst', 'fahren'], exp: 'fahren changes a → ä in du/er: er fährt.' },
      { p: 'Wir ___ in einem Krankenhaus. (arbeiten)', en: 'We work in a hospital.', o: ['arbeiten', 'arbeitet', 'arbeite', 'arbeitest'], exp: 'wir → -en: wir arbeiten.' },
      { p: 'Du ___ zu viel. (arbeiten)', en: 'You work too much.', o: ['arbeitest', 'arbeitst', 'arbeitet', 'arbeiten'], exp: 'Stem ends in -t → extra -e-: du arbeitest.' },
      { p: 'Wie ___ du? – Ich heiße Priya. (heißen)', en: 'What is your name? – My name is Priya.', o: ['heißt', 'heißst', 'heißest', 'heiße'], exp: 'Stem ends in -ß → du only adds -t: du heißt.' },
      { p: 'Sie ___ gern Romane. (lesen, she)', en: 'She likes reading novels.', o: ['liest', 'lest', 'lesen', 'liesst'], exp: 'lesen changes e → ie, and s + st → st: sie liest.' },
      { p: '___ ihr heute Abend Zeit? (haben)', en: 'Do you (all) have time tonight?', o: ['Habt', 'Haben', 'Hast', 'Hat'], exp: 'ihr → -t: ihr habt.' },
      { p: 'Ich ___ aus Chennai. (sein)', en: 'I am from Chennai.', o: ['bin', 'ist', 'bist', 'sind'], exp: 'sein is irregular: ich bin, du bist, er ist.' },
      { p: 'Das Kind ___ schnell. (laufen)', en: 'The child runs fast.', o: ['läuft', 'lauft', 'läufst', 'laufen'], exp: 'laufen changes au → äu in du/er: es läuft.' },
      { p: 'Herr Weber, ___ Sie Kaffee oder Tee? (möchten)', en: 'Mr Weber, would you like coffee or tea?', o: ['möchten', 'möchtest', 'möchte', 'möchtet'], exp: 'Formal Sie always takes the -en form (like sie plural).' },
      { p: 'Er ___ seinem Freund das Buch. (geben)', en: 'He gives his friend the book.', o: ['gibt', 'gebt', 'gibst', 'geben'], exp: 'geben changes e → i: er gibt.' },
      { p: 'Mein Bruder ___ bis 9 Uhr. (schlafen)', en: 'My brother sleeps until 9 o\'clock.', o: ['schläft', 'schlaft', 'schläfst', 'schlafen'], exp: 'schlafen changes a → ä: er schläft.' }] },

  { id: 'a1_pronomen', level: 'A1', category: 'Pronouns', color: 'var(--blue)',
    title: 'Personalpronomen & Possessivartikel (ich/mich/mir · mein/meinen/meinem)',
    summary: 'Pronouns change with the case, exactly like Tamil நான் / என்னை / எனக்கு. Possessive articles (mein, dein, sein …) take the same endings as ein / kein.',
    formula: '• Nominativ (who?) → Akkusativ (whom? direct object) → Dativ (to whom?)\n• ich → mich → mir · du → dich → dir · er → ihn → ihm · sie → sie → ihr · es → es → ihm\n• wir → uns → uns · ihr → euch → euch · sie/Sie → sie/Sie → ihnen/Ihnen\n• Possessive: ich→mein, du→dein, er/es→sein, sie→ihr, wir→unser, ihr→euer, sie→ihr, Sie→Ihr — endings like ein/kein (meinen Vater, meiner Mutter)',
    tableHTML: T([['Nominativ', 'Akkusativ', 'Dativ', 'Possessiv', 'Tamil'],
      ['ich', '<b>mich</b>', '<b>mir</b>', 'mein', 'நான் · என்னை · எனக்கு · என்'], ['du', '<b>dich</b>', '<b>dir</b>', 'dein', 'நீ · உன்னை · உனக்கு · உன்'],
      ['er', '<b>ihn</b>', '<b>ihm</b>', 'sein', 'அவன் · அவனை · அவனுக்கு · அவனுடைய'], ['sie', 'sie', '<b>ihr</b>', 'ihr', 'அவள் · அவளை · அவளுக்கு · அவளுடைய'],
      ['es', 'es', '<b>ihm</b>', 'sein', 'அது · அதை · அதற்கு · அதனுடைய'], ['wir', '<b>uns</b>', '<b>uns</b>', 'unser', 'நாம்/நாங்கள் · நம்மை · நமக்கு · நம்'],
      ['ihr', '<b>euch</b>', '<b>euch</b>', 'euer', 'நீங்கள் · உங்களை · உங்களுக்கு · உங்கள்'], ['sie / Sie', 'sie / Sie', '<b>ihnen / Ihnen</b>', 'ihr / Ihr', 'அவர்கள் · அவர்களை · அவர்களுக்கு · அவர்களுடைய']])
      + '<div style="margin-top:8px;"></div>' + T([['mein …', 'der Vater', 'die Mutter', 'das Kind', 'die Eltern (Pl.)'],
      ['Nominativ', 'mein Vater', 'mein<b>e</b> Mutter', 'mein Kind', 'mein<b>e</b> Eltern'], ['Akkusativ', 'mein<b>en</b> Vater', 'mein<b>e</b> Mutter', 'mein Kind', 'mein<b>e</b> Eltern'],
      ['Dativ', 'mein<b>em</b> Vater', 'mein<b>er</b> Mutter', 'mein<b>em</b> Kind', 'mein<b>en</b> Eltern']]),
    examples: [{ de: 'Kannst du mir helfen? – Ja, ich helfe dir.', en: 'Can you help me? – Yes, I\'ll help you. (helfen + Dativ)' },
      { de: 'Ich sehe ihn jeden Tag.', en: 'I see him every day. (Akkusativ)' },
      { de: 'Das ist mein Bruder und das ist seine Frau.', en: 'This is my brother and this is his wife.' }],
    bank: [
      { p: 'Kennst du Thomas? – Ja, ich kenne ___ gut.', en: 'Do you know Thomas? – Yes, I know him well.', o: ['ihn', 'ihm', 'er', 'sein'], exp: 'kennen + Akkusativ: er → ihn.' },
      { p: 'Kannst du ___ bitte helfen?', en: 'Can you help me, please?', o: ['mir', 'mich', 'ich', 'mein'], exp: 'helfen takes the Dativ: ich → mir.' },
      { p: 'Ich rufe ___ morgen an, Frau Schmidt.', en: 'I\'ll call you tomorrow, Mrs Schmidt.', o: ['Sie', 'Ihnen', 'ihr', 'dich'], exp: 'anrufen + Akkusativ; formal Sie stays Sie in the Akkusativ.' },
      { p: 'Wie geht es ___, Herr Weber?', en: 'How are you, Mr Weber?', o: ['Ihnen', 'Sie', 'Ihr', 'dir'], exp: 'es geht + Dativ: formal Sie → Ihnen.' },
      { p: 'Das Geschenk ist für ___. (du)', en: 'The present is for you.', o: ['dich', 'dir', 'du', 'dein'], exp: 'für always takes the Akkusativ: du → dich.' },
      { p: 'Ich wohne bei ___ Eltern.', en: 'I live with my parents.', o: ['meinen', 'meine', 'meiner', 'meinem'], exp: 'bei + Dativ, plural → meinen Eltern.' },
      { p: 'Maria sucht ___ Schlüssel. (her)', en: 'Maria is looking for her key.', o: ['ihren', 'ihr', 'seinen', 'ihrem'], exp: 'Maria → ihr-; der Schlüssel is Akkusativ masculine → ihren.' },
      { p: 'Paul besucht ___ Oma am Sonntag.', en: 'Paul visits his grandma on Sunday.', o: ['seine', 'seinen', 'ihre', 'seiner'], exp: 'Paul → sein-; die Oma, Akkusativ feminine → seine.' },
      { p: 'Die Kinder spielen. Ich gebe ___ einen Ball.', en: 'The children are playing. I give them a ball.', o: ['ihnen', 'sie', 'ihr', 'euch'], exp: 'geben + Dativ (to whom?) plural → ihnen.' },
      { p: 'Wir fahren mit ___ Auto. (our)', en: 'We are going in our car.', o: ['unserem', 'unser', 'unseren', 'unsere'], exp: 'mit + Dativ, das Auto → unserem Auto.' },
      { p: 'Gefällt ___ die Wohnung? (ihr, you all)', en: 'Do you (all) like the flat?', o: ['euch', 'ihr', 'eure', 'Ihnen'], exp: 'gefallen + Dativ: ihr → euch.' },
      { p: 'Das ist nicht mein Handy. Ist das ___ Handy? (du)', en: 'That\'s not my phone. Is it your phone?', o: ['dein', 'deine', 'deinen', 'dich'], exp: 'das Handy, Nominativ neuter → dein.' }] },

  { id: 'a1_negation', level: 'A1', category: 'Syntax', color: 'var(--red)',
    title: 'Negation: nicht, kein, doch, nichts, nie',
    summary: 'kein replaces the article ein / no article ("not a / no"). nicht negates everything else. When someone asks a negative question and you mean YES, answer "Doch!".',
    formula: '• kein = ein/— + not: Ich habe kein Auto. Ich trinke keinen Kaffee. (endings like ein: keinen, keinem …)\n• nicht for verbs, names, der/die/das nouns, adjectives, adverbs: Ich komme nicht. Das ist nicht mein Buch.\n• Position of nicht: at the end of the sentence (Ich kenne ihn nicht) BUT before an adjective, a prepositional phrase, the 2nd verb part and most adverbs: Er ist nicht müde · Ich fahre nicht nach Berlin · Ich habe es nicht gesehen\n• Answering: positive question → Ja / Nein. Negative question ("Kommst du nicht?") → Doch! (= yes, I do) / Nein.\n• Also: nichts (nothing), niemand (nobody), nie (never), nirgends (nowhere)',
    tableHTML: T([['Positive', 'Negative', 'Rule'], ['Ich habe <b>ein</b> Auto.', 'Ich habe <b>kein</b> Auto.', 'ein → kein'], ['Ich trinke Kaffee.', 'Ich trinke <b>keinen</b> Kaffee.', 'no article → kein (Akk. masc. -en)'],
      ['Ich komme.', 'Ich komme <b>nicht</b>.', 'verb → nicht at the end'], ['Er ist müde.', 'Er ist <b>nicht</b> müde.', 'before the adjective'], ['Ich fahre nach Berlin.', 'Ich fahre <b>nicht</b> nach Berlin.', 'before the place phrase'],
      ['Ich habe es gesehen.', 'Ich habe es <b>nicht</b> gesehen.', 'before the 2nd verb part'], ['Kommst du nicht? – ', '<b>Doch</b>, ich komme!', 'yes to a negative question']]),
    examples: [{ de: 'Ich habe keine Zeit.', en: 'I have no time.' }, { de: 'Das verstehe ich nicht.', en: 'I don\'t understand that.' }, { de: 'Hast du keinen Hunger? – Doch, großen Hunger!', en: 'Aren\'t you hungry? – Yes I am, very hungry!' }],
    bank: [
      { p: 'Ich habe ___ Bruder.', en: 'I don\'t have a brother.', o: ['keinen', 'kein', 'nicht', 'keine'], exp: 'ein Bruder → kein; Akkusativ masculine → keinen.' },
      { p: 'Heute scheint die Sonne ___.', en: 'The sun isn\'t shining today.', o: ['nicht', 'kein', 'keine', 'nichts'], exp: 'Negating the verb → nicht at the end.' },
      { p: 'Das ist ___ gute Idee.', en: 'That is not a good idea.', o: ['keine', 'nicht', 'kein', 'keinen'], exp: 'eine Idee → keine Idee.' },
      { p: 'Er ist ___ zu Hause.', en: 'He is not at home.', o: ['nicht', 'kein', 'keine', 'nie'], exp: 'Before a place phrase → nicht.' },
      { p: 'Kommst du nicht mit? – ___, ich komme mit!', en: 'Aren\'t you coming along? – Yes, I am!', o: ['Doch', 'Ja', 'Nein', 'Nicht'], exp: 'Yes to a negative question = Doch.' },
      { p: 'Ich trinke ___ Alkohol.', en: 'I don\'t drink alcohol.', o: ['keinen', 'nicht', 'kein', 'keine'], exp: 'Noun without article → kein; der Alkohol, Akk. → keinen.' },
      { p: 'Ich habe den Film ___ gesehen.', en: 'I haven\'t seen the film.', o: ['nicht', 'kein', 'keinen', 'nichts'], exp: 'den Film (definite) → nicht, before the participle.' },
      { p: 'Im Kühlschrank ist ___. Wir müssen einkaufen.', en: 'There is nothing in the fridge. We have to go shopping.', o: ['nichts', 'nicht', 'kein', 'niemand'], exp: 'nothing = nichts.' },
      { p: 'Ich rauche ___. Nicht einmal auf Partys.', en: 'I never smoke. Not even at parties.', o: ['nie', 'nichts', 'kein', 'niemand'], exp: 'never = nie.' },
      { p: 'Hast du Kinder? – Nein, ich habe ___ Kinder.', en: 'Do you have children? – No, I have no children.', o: ['keine', 'kein', 'keinen', 'nicht'], exp: 'Plural → keine.' }] },

  { id: 'a1_fragen', level: 'A1', category: 'Syntax', color: 'var(--green)',
    title: 'Fragen: W-Fragen, Ja/Nein-Fragen, welcher & was für ein',
    summary: 'W-questions keep the verb in position 2. Yes/no questions start with the verb. Tamil just adds -ஆ at the end (போகிறாயா?) — German moves the verb instead.',
    formula: '• W-Frage: W-word (1) + verb (2) + subject …? → Wo wohnst du?\n• Ja/Nein-Frage: verb (1) + subject …? → Wohnst du in Berlin?\n• Wer (who) · Was (what) · Wo (where) · Wohin (where to) · Woher (where from) · Wann (when) · Wie (how) · Warum (why) · Wie viel (how much) · Wie viele (how many) · Wie lange (how long)\n• Welcher/welche/welches? = which (from a known set, endings like der) · Was für ein? = what kind of (endings like ein)\n• Wen? (whom, Akk.) · Wem? (to whom, Dat.) · Wessen? (whose)',
    tableHTML: T([['Question word', 'Meaning', 'Example'], ['Wer?', 'who', '<b>Wer</b> ist das?'], ['Was?', 'what', '<b>Was</b> machst du?'], ['Wo? / Wohin? / Woher?', 'where / where to / where from', '<b>Woher</b> kommst du?'],
      ['Wann?', 'when', '<b>Wann</b> beginnt der Kurs?'], ['Wie? / Wie viel(e)?', 'how / how much (many)', '<b>Wie viele</b> Kinder haben Sie?'], ['Warum?', 'why', '<b>Warum</b> lernst du Deutsch?'],
      ['Welcher?', 'which (known choice)', '<b>Welchen</b> Bus nimmst du?'], ['Was für ein?', 'what kind of', '<b>Was für ein</b> Auto hast du?'], ['— (verb first)', 'yes/no', '<b>Hast</b> du Zeit?']]),
    examples: [{ de: 'Woher kommst du? – Ich komme aus Indien.', en: 'Where are you from? – I am from India.' }, { de: 'Sprechen Sie Englisch?', en: 'Do you speak English? (verb first)' }, { de: 'Welche Jacke nimmst du, die rote oder die blaue?', en: 'Which jacket are you taking, the red or the blue one?' }],
    bank: [
      { p: '___ wohnst du? – In Stuttgart.', en: 'Where do you live? – In Stuttgart.', o: ['Wo', 'Wohin', 'Woher', 'Wann'], exp: 'Place (no movement) → Wo?' },
      { p: '___ fährst du im Urlaub? – Nach Italien.', en: 'Where are you going on holiday? – To Italy.', o: ['Wohin', 'Wo', 'Woher', 'Wie'], exp: 'Direction → Wohin?' },
      { p: '___ kommen Sie? – Aus Sri Lanka.', en: 'Where are you from? – From Sri Lanka.', o: ['Woher', 'Wo', 'Wohin', 'Wer'], exp: 'Origin → Woher?' },
      { p: '___ kostet das Brot? – 3 Euro.', en: 'How much is the bread? – 3 euros.', o: ['Wie viel', 'Wie viele', 'Was', 'Wann'], exp: 'Price / uncountable → Wie viel.' },
      { p: '___ Geschwister hast du?', en: 'How many siblings do you have?', o: ['Wie viele', 'Wie viel', 'Welche', 'Was'], exp: 'Countable plural → Wie viele.' },
      { p: '___ du heute Zeit?', en: 'Do you have time today?', o: ['Hast', 'Hat', 'Haben', 'Habt'], exp: 'Yes/no question: verb first, du → hast.' },
      { p: '___ Film möchtest du sehen – den Krimi oder die Komödie?', en: 'Which film do you want to see – the thriller or the comedy?', o: ['Welchen', 'Welcher', 'Was für einen', 'Welches'], exp: 'Choice from known options → welch-; der Film, Akk. → welchen.' },
      { p: '___ Auto hast du? – Einen kleinen Elektrowagen.', en: 'What kind of car do you have? – A small electric car.', o: ['Was für ein', 'Welches', 'Wie', 'Was'], exp: 'Asking for the kind → was für ein.' },
      { p: '___ hast du gestern gesehen? – Meinen Chef.', en: 'Whom did you see yesterday? – My boss.', o: ['Wen', 'Wem', 'Wer', 'Wessen'], exp: 'Akkusativ person → Wen?' },
      { p: '___ gehört die Tasche? – Meiner Schwester.', en: 'Whose is the bag? (To whom does it belong?)', o: ['Wem', 'Wen', 'Wer', 'Was'], exp: 'gehören + Dativ → Wem?' }] },

  { id: 'a1_zahlen_zeit', level: 'A1', category: 'Basics', color: 'var(--gold)',
    title: 'Zahlen, Uhrzeit & Datum (einundzwanzig · halb drei · am dritten Mai)',
    summary: 'German says the units first (21 = one-and-twenty), "halb drei" means 2:30 (half TOWARDS three), and dates use ordinal numbers: am dritten Mai.',
    formula: '• 13–19: dreizehn … neunzehn (sechzehn, siebzehn!) · 21–99: unit + und + ten: einundzwanzig, siebenundvierzig · 100 hundert · 1000 tausend\n• Time (official): 14:30 = vierzehn Uhr dreißig · (everyday): Viertel nach zwei (2:15) · halb drei (2:30!) · Viertel vor drei (2:45) · fünf vor halb drei (2:25)\n• um + time: um 8 Uhr · am + day/date/part of day: am Montag, am 3. Mai, am Abend · im + month/season: im Mai, im Winter · in der Nacht\n• Ordinal: 1. erste, 2. zweite, 3. dritte, 7. siebte, 8. achte, from 20: -ste (zwanzigste) → Heute ist der dritte Mai. · Am dritten Mai habe ich Geburtstag.',
    tableHTML: `<div class="prep-grid" style="grid-template-columns:repeat(auto-fill, minmax(120px, 1fr));">${clock(2, 15, 'Viertel nach zwei')}${clock(2, 30, 'halb drei (2:30!)')}${clock(2, 45, 'Viertel vor drei')}${clock(2, 25, 'fünf vor halb drei')}${clock(2, 35, 'fünf nach halb drei')}${clock(7, 0, 'sieben Uhr')}</div>`
      + T([['Number', 'German', 'Tip'], ['16 / 17', 'sechzehn / siebzehn', 'drop -s / -en'], ['21', 'ein<b>und</b>zwanzig', 'unit first'], ['35', 'fünfunddreißig', 'dreißig with ß'], ['99', 'neunundneunzig', ''], ['101', 'hunderteins', ''], ['2024', 'zweitausendvierundzwanzig', 'years: no "im", or "im Jahr 2024"'],
        ['1. / 3. / 7.', 'der erste / dritte / siebte', 'irregular ordinals'], ['20.', 'der zwanzigste', 'from 20: -ste']]),
    examples: [{ de: 'Der Kurs beginnt um halb neun.', en: 'The course starts at 8:30.' }, { de: 'Am dritten Oktober ist Feiertag.', en: 'The 3rd of October is a public holiday.' }, { de: 'Das kostet einundzwanzig Euro.', en: 'That costs 21 euros.' }],
    bank: [
      { p: '8:30 Uhr = ___', en: 'half past eight', o: ['halb neun', 'halb acht', 'acht Uhr halb', 'neun halb'], exp: 'halb + NEXT hour: 8:30 = halb neun.' },
      { p: '6:15 Uhr = ___', en: 'quarter past six', o: ['Viertel nach sechs', 'Viertel vor sechs', 'Viertel vor sieben', 'halb sieben'], exp: ':15 = Viertel nach + current hour.' },
      { p: '10:45 Uhr = ___', en: 'quarter to eleven', o: ['Viertel vor elf', 'Viertel nach zehn', 'Viertel vor zehn', 'halb elf'], exp: ':45 = Viertel vor + next hour.' },
      { p: '47 = ___', en: 'forty-seven', o: ['siebenundvierzig', 'vierzigsieben', 'vierundsiebzig', 'siebzigvier'], exp: 'Unit first: sieben-und-vierzig.' },
      { p: 'Der Termin ist ___ 9 Uhr.', en: 'The appointment is at 9 o\'clock.', o: ['um', 'am', 'im', 'an'], exp: 'Clock time → um.' },
      { p: 'Ich habe ___ Montag frei.', en: 'I am off on Monday.', o: ['am', 'um', 'im', 'in'], exp: 'Days → am.' },
      { p: '___ Sommer fahren wir nach Indien.', en: 'In summer we are going to India.', o: ['Im', 'Am', 'Um', 'In'], exp: 'Seasons and months → im.' },
      { p: 'Heute ist der ___ Juli. (3.)', en: 'Today is the 3rd of July.', o: ['dritte', 'dreite', 'dreiste', 'dritten'], exp: 'Nominativ after der: der dritte (irregular: drei → dritte).' },
      { p: 'Ich habe am ___ Mai Geburtstag. (7.)', en: 'My birthday is on the 7th of May.', o: ['siebten', 'siebte', 'siebenten', 'siebenste'], exp: 'am + ordinal → -en: am siebten.' },
      { p: '16 = ___', en: 'sixteen', o: ['sechzehn', 'sechszehn', 'sechsehn', 'sechzig'], exp: 'sechzehn — the -s of sechs is dropped.' },
      { p: 'Wir treffen uns ___ Abend.', en: 'We are meeting in the evening.', o: ['am', 'um', 'im', 'in'], exp: 'Part of the day → am (but: in der Nacht).' }] },

  { id: 'a1_modalverben', level: 'A1', category: 'Verbs', color: 'var(--purple)',
    title: 'Modalverben: können, müssen, wollen, möchten, dürfen, sollen',
    summary: 'A modal verb stands in position 2, the main verb goes to the END as an infinitive — the same order as Tamil: "fahren muss" = "போக வேண்டும்". ich and er have the SAME form, without an ending.',
    formula: '• Sentence: subject + modal (pos. 2) + … + infinitive (end): Ich muss heute arbeiten.\n• ich/er/sie/es: no ending and often another vowel: ich kann, er kann · ich muss, er muss · ich will · ich darf · ich soll · ich möchte\n• können = can / be able · müssen = must / have to · wollen = want · möchten = would like · dürfen = may / be allowed · sollen = should / be supposed to\n• nicht müssen = don\'t have to · nicht dürfen = must not (see rule "Modalverben Nuancen")',
    tableHTML: T([['', 'können', 'müssen', 'wollen', 'dürfen', 'sollen', 'möchten'],
      ['ich', '<b>kann</b>', '<b>muss</b>', '<b>will</b>', '<b>darf</b>', 'soll', 'möchte'], ['du', 'kannst', 'musst', 'willst', 'darfst', 'sollst', 'möchtest'], ['er/sie/es', '<b>kann</b>', '<b>muss</b>', '<b>will</b>', '<b>darf</b>', 'soll', 'möchte'],
      ['wir', 'können', 'müssen', 'wollen', 'dürfen', 'sollen', 'möchten'], ['ihr', 'könnt', 'müsst', 'wollt', 'dürft', 'sollt', 'möchtet'], ['sie/Sie', 'können', 'müssen', 'wollen', 'dürfen', 'sollen', 'möchten']]),
    examples: [{ de: 'Ich kann gut kochen.', en: 'I can cook well.' }, { de: 'Hier darf man nicht parken.', en: 'You are not allowed to park here.' }, { de: 'Möchtest du etwas trinken?', en: 'Would you like something to drink?' }],
    bank: [
      { p: 'Er ___ sehr gut schwimmen.', en: 'He can swim very well.', o: ['kann', 'kannt', 'können', 'kannst'], exp: 'er → kann (no ending).' },
      { p: 'Ich ___ morgen früh aufstehen.', en: 'I have to get up early tomorrow.', o: ['muss', 'musse', 'müsse', 'musst'], exp: 'ich → muss.' },
      { p: 'Hier ___ man nicht rauchen.', en: 'Smoking is not allowed here.', o: ['darf', 'dürft', 'darfst', 'dürfen'], exp: 'man → like er: darf.' },
      { p: '___ du mir helfen?', en: 'Can you help me?', o: ['Kannst', 'Kann', 'Könnt', 'Können'], exp: 'du → kannst.' },
      { p: 'Ich möchte einen Kaffee ___.', en: 'I would like to drink a coffee.', o: ['trinken', 'trinke', 'trinkt', 'getrunken'], exp: 'The main verb goes to the end as infinitive.' },
      { p: 'Die Kinder ___ Eis essen.', en: 'The children want to eat ice cream.', o: ['wollen', 'will', 'wollt', 'willst'], exp: 'sie (plural) → wollen.' },
      { p: 'Der Arzt sagt, ich ___ weniger Zucker essen.', en: 'The doctor says I should eat less sugar.', o: ['soll', 'sollst', 'sollen', 'darf'], exp: 'Advice/instruction from another person → sollen; ich → soll.' },
      { p: 'Ihr ___ heute nicht arbeiten, es ist Sonntag.', en: 'You don\'t have to work today, it\'s Sunday.', o: ['müsst', 'müssen', 'musst', 'dürft'], exp: 'ihr → müsst; nicht müssen = don\'t have to.' },
      { p: 'Wann ___ Sie kommen? – Um 10 Uhr.', en: 'When can you come? – At 10.', o: ['können', 'kann', 'könnt', 'kannst'], exp: 'Sie → können.' }] },

  { id: 'a1_trennbar', level: 'A1', category: 'Verbs', color: 'var(--green)',
    title: 'Trennbare & untrennbare Verben (anrufen · besuchen)',
    summary: 'Separable prefixes (an-, auf-, aus-, ein-, mit-, zu-, zurück-, fern-, weg-, vor-) jump to the END in a main clause. Inseparable prefixes (be-, emp-, ent-, er-, ge-, miss-, ver-, zer-) never move and get no ge- in the Perfekt.',
    formula: '• Main clause: prefix at the end → Ich rufe dich morgen an. (anrufen)\n• With modal / Nebensatz: verb stays together at the end → Ich muss dich anrufen · …, weil ich dich anrufe.\n• Perfekt: separable → ge in the middle: an·ge·rufen, ein·ge·kauft · inseparable → no ge: besucht, verstanden, erklärt\n• zu-Infinitiv: separable → anzurufen · inseparable → zu besuchen\n• Separable prefixes are stressed (ANrufen), inseparable ones are not (beSUCHen).',
    tableHTML: T([['Verb', 'Präsens', 'Perfekt', 'Modal / Nebensatz'], ['<b>an</b>rufen', 'Ich rufe dich <b>an</b>.', 'Ich habe dich an<b>ge</b>rufen.', 'Ich will dich anrufen.'], ['<b>ein</b>kaufen', 'Wir kaufen heute <b>ein</b>.', 'Wir haben ein<b>ge</b>kauft.', '…, weil wir einkaufen.'],
      ['<b>auf</b>stehen', 'Ich stehe um 6 Uhr <b>auf</b>.', 'Ich bin aufgestanden.', 'Ich muss früh aufstehen.'], ['<b>fern</b>sehen', 'Er sieht jeden Abend <b>fern</b>.', 'Er hat ferngesehen.', '…, dass er fernsieht.'],
      ['<b>be</b>suchen', 'Ich besuche meine Oma.', 'Ich habe sie besucht. (no ge!)', 'Ich will sie besuchen.'], ['<b>ver</b>stehen', 'Ich verstehe das.', 'Ich habe es verstanden.', '…, weil ich es verstehe.']]),
    examples: [{ de: 'Der Zug fährt um 8 Uhr ab.', en: 'The train leaves at 8.' }, { de: 'Kannst du bitte das Fenster aufmachen?', en: 'Can you open the window, please?' }, { de: 'Ich habe das Wort nicht verstanden.', en: 'I didn\'t understand the word.' }],
    bank: [
      { p: 'Ich ___ meine Mutter jeden Sonntag ___. (anrufen)', en: 'I call my mother every Sunday.', o: ['rufe … an', 'anrufe … —', 'rufe an … —', 'an … rufe'], exp: 'Main clause: conjugated part in position 2, prefix at the end.' },
      { p: 'Wann ___ der Film? (anfangen)', en: 'When does the film start?', o: ['fängt … an', 'anfängt', 'fängt an …', 'angefangen'], exp: 'Wann fängt der Film an?' },
      { p: 'Ich habe gestern viel ___. (einkaufen)', en: 'I did a lot of shopping yesterday.', o: ['eingekauft', 'geeinkauft', 'einkauft', 'eingekaufen'], exp: 'Separable: ge between prefix and stem → eingekauft.' },
      { p: 'Wir haben unsere Freunde ___. (besuchen)', en: 'We visited our friends.', o: ['besucht', 'gebesucht', 'begesucht', 'besuchen'], exp: 'Inseparable be- → no ge: besucht.' },
      { p: 'Ich kann heute nicht ___. (mitkommen)', en: 'I can\'t come along today.', o: ['mitkommen', 'komme mit', 'mitgekommen', 'mit kommen'], exp: 'With a modal the verb stays together at the end.' },
      { p: 'Er sagt, dass er um 7 Uhr ___. (aufstehen)', en: 'He says that he gets up at 7.', o: ['aufsteht', 'steht auf', 'aufstehen', 'auf steht'], exp: 'Nebensatz: verb together at the end → aufsteht.' },
      { p: 'Ich habe keine Lust, ___. (aufräumen)', en: 'I don\'t feel like tidying up.', o: ['aufzuräumen', 'zu aufräumen', 'aufräumen zu', 'aufgeräumt'], exp: 'zu goes between prefix and stem: aufzuräumen.' },
      { p: 'Hast du das ___? (verstehen)', en: 'Did you understand that?', o: ['verstanden', 'geverstanden', 'verstehen', 'vergestanden'], exp: 'ver- is inseparable → no ge: verstanden.' }] },

  { id: 'a1_imperativ', level: 'A1', category: 'Verbs', color: 'var(--red)',
    title: 'Imperativ (Komm! · Kommt! · Kommen Sie!)',
    summary: 'Commands and requests. The du-form is the verb stem (no -st, no du). With "bitte" or "mal" it sounds friendly. Tamil also has a plain form (வா) and a polite form (வாருங்கள்) — like du vs Sie.',
    formula: '• du: stem, no pronoun → Komm! Mach! Hilf! (e→i stays: sprechen → Sprich!) but a→ä does NOT: fahren → Fahr!\n• ihr: ihr-form without ihr → Kommt! Macht!\n• Sie: verb + Sie → Kommen Sie! Warten Sie bitte!\n• wir (let\'s): Gehen wir!\n• sein: Sei! · Seid! · Seien Sie! · Separable: Ruf mich an! Mach das Fenster auf!',
    tableHTML: T([['Infinitiv', 'du', 'ihr', 'Sie'], ['kommen', '<b>Komm!</b>', 'Kommt!', 'Kommen Sie!'], ['sprechen', '<b>Sprich</b> langsam!', 'Sprecht!', 'Sprechen Sie!'], ['fahren', '<b>Fahr</b> vorsichtig! (no ä)', 'Fahrt!', 'Fahren Sie!'],
      ['warten', '<b>Warte</b>! (-t → -e)', 'Wartet!', 'Warten Sie!'], ['sein', '<b>Sei</b> leise!', 'Seid leise!', 'Seien Sie leise!'], ['anrufen', '<b>Ruf</b> mich <b>an</b>!', 'Ruft an!', 'Rufen Sie an!']]),
    examples: [{ de: 'Hilf mir bitte!', en: 'Help me, please!' }, { de: 'Setzen Sie sich bitte.', en: 'Please sit down.' }, { de: 'Mach mal das Licht aus!', en: 'Switch off the light, will you!' }],
    bank: [
      { p: '___ bitte langsamer! (sprechen, du)', en: 'Please speak more slowly!', o: ['Sprich', 'Sprech', 'Sprichst', 'Sprecht'], exp: 'e → i stays in the du-imperative: Sprich!' },
      { p: '___ vorsichtig! (fahren, du)', en: 'Drive carefully!', o: ['Fahr', 'Fähr', 'Fährst', 'Fahrst'], exp: 'a → ä does NOT happen in the imperative: Fahr!' },
      { p: '___ Sie bitte einen Moment! (warten)', en: 'Please wait a moment!', o: ['Warten', 'Wartet', 'Warte', 'Wartest'], exp: 'Sie-form = infinitive + Sie.' },
      { p: 'Kinder, ___ leise! (sein)', en: 'Children, be quiet!', o: ['seid', 'sind', 'sei', 'seien'], exp: 'ihr-imperative of sein → Seid!' },
      { p: '___ mich morgen ___! (anrufen, du)', en: 'Call me tomorrow!', o: ['Ruf … an', 'Anruf … —', 'Rufe an … —', 'Rufst … an'], exp: 'Separable prefix goes to the end: Ruf mich an!' },
      { p: '___ nicht so laut! (sein, du)', en: 'Don\'t be so loud!', o: ['Sei', 'Bist', 'Seid', 'Sein'], exp: 'du-imperative of sein → Sei!' },
      { p: '___ mir bitte! (helfen, du)', en: 'Help me, please!', o: ['Hilf', 'Helf', 'Hilfst', 'Helft'], exp: 'helfen → du hilfst → Hilf!' }] },

  /* ============================ A2 ============================ */
  { id: 'a2_perfekt', level: 'A2', category: 'Tenses', color: 'var(--blue)',
    title: 'Perfekt: haben oder sein + Partizip II (gemacht · gegangen · besucht)',
    summary: 'Spoken past tense. haben/sein in position 2, the Partizip II at the END. Most verbs use haben; verbs of movement (A → B) and change of state use sein.',
    formula: '• haben/sein (pos. 2) + … + Partizip II (end): Ich habe gestern Pizza gegessen.\n• sein: movement from A to B (gehen, fahren, fliegen, kommen, laufen), change of state (aufstehen, einschlafen, sterben, werden, wachsen) + sein, bleiben, passieren\n• Weak verbs: ge-…-t → machen → gemacht, kaufen → gekauft · Strong verbs: ge-…-en (often new vowel) → gehen → gegangen, trinken → getrunken\n• Separable: ge in the middle → eingekauft, angerufen · No ge: inseparable (besucht, verstanden, erklärt) and -ieren verbs (studiert, telefoniert)\n• In speech, sein, haben and the modal verbs usually use the Präteritum: war, hatte, konnte, musste',
    tableHTML: T([['Type', 'Infinitiv', 'Perfekt'], ['weak', 'machen', 'hat <b>ge</b>mach<b>t</b>'], ['strong', 'trinken', 'hat <b>ge</b>trunk<b>en</b>'], ['movement → sein', 'fahren', '<b>ist</b> gefahren'],
      ['change of state → sein', 'einschlafen', '<b>ist</b> eingeschlafen'], ['separable', 'einkaufen', 'hat ein<b>ge</b>kauft'], ['inseparable', 'besuchen', 'hat besucht (no ge)'], ['-ieren', 'studieren', 'hat studiert (no ge)'], ['mixed', 'bringen / denken / wissen', 'hat gebracht / gedacht / gewusst']]),
    examples: [{ de: 'Am Wochenende bin ich nach München gefahren.', en: 'At the weekend I went to Munich.' }, { de: 'Hast du schon gegessen?', en: 'Have you eaten yet?' }, { de: 'Ich habe drei Jahre in Chennai studiert.', en: 'I studied in Chennai for three years.' }],
    bank: [
      { p: 'Gestern ___ ich ins Kino gegangen.', en: 'Yesterday I went to the cinema.', o: ['bin', 'habe', 'war', 'hatte'], exp: 'gehen = movement → sein: ich bin gegangen.' },
      { p: 'Wir ___ viel Kaffee getrunken.', en: 'We drank a lot of coffee.', o: ['haben', 'sind', 'hatten', 'waren'], exp: 'trinken (no movement) → haben.' },
      { p: 'Ich habe dich gestern ___. (anrufen)', en: 'I called you yesterday.', o: ['angerufen', 'geangerufen', 'anrufen', 'angeruft'], exp: 'Separable + strong: an-ge-rufen.' },
      { p: 'Er hat Medizin ___. (studieren)', en: 'He studied medicine.', o: ['studiert', 'gestudiert', 'studieret', 'gestudieren'], exp: '-ieren verbs take no ge-: studiert.' },
      { p: 'Das Baby ___ endlich eingeschlafen.', en: 'The baby has finally fallen asleep.', o: ['ist', 'hat', 'war', 'wird'], exp: 'Change of state → sein.' },
      { p: 'Was ___ passiert?', en: 'What happened?', o: ['ist', 'hat', 'war', 'wird'], exp: 'passieren always uses sein.' },
      { p: 'Ich habe das Buch ___. (lesen)', en: 'I have read the book.', o: ['gelesen', 'gelest', 'gelesst', 'lesen'], exp: 'Strong verb: gelesen.' },
      { p: 'Sie ___ zwei Wochen in Indien geblieben.', en: 'She stayed in India for two weeks.', o: ['ist', 'hat', 'war', 'wird'], exp: 'bleiben uses sein (like sein itself).' },
      { p: 'Wir haben unsere Tante ___. (besuchen)', en: 'We visited our aunt.', o: ['besucht', 'gebesucht', 'besuchen', 'besuchet'], exp: 'Inseparable be- → no ge.' },
      { p: 'Ich habe es nicht ___. (wissen)', en: 'I didn\'t know it.', o: ['gewusst', 'gewisst', 'gewissen', 'gewiesen'], exp: 'Mixed verb: wissen → gewusst.' }] },

  { id: 'a2_komparation', level: 'A2', category: 'Adjectives', color: 'var(--gold)',
    title: 'Komparativ & Superlativ (schön · schöner · am schönsten)',
    summary: 'Comparative = adjective + -er, superlative = am … -sten. Short words with a/o/u often get an umlaut. Compare with "als" (different) or "so … wie" (equal). Tamil: "அவனை விட உயரம்" = größer als er.',
    formula: '• Komparativ: -er (schneller) · Superlativ: am …-sten (am schnellsten) / der, die, das …-ste (der schnellste Zug)\n• Umlaut in short a/o/u words: alt → älter, groß → größer, jung → jünger, kurz → kürzer, warm → wärmer\n• -d / -t / -s / -ß / -sch / -x / -z → -esten: am breitesten, am wildesten, am heißesten, am hübschesten (but groß → am größten)\n• Unstressed -end / -isch: only -sten: am spannendsten, am praktischsten\n• -el / -er drop the e in the Komparativ: dunkel → dunkler, teuer → teurer (am dunkelsten, am teuersten)\n• Irregular: gut – besser – am besten · viel – mehr – am meisten · gern – lieber – am liebsten · hoch – höher – am höchsten · nah – näher – am nächsten\n• größer ALS · (genau)so groß WIE',
    tableHTML: bars([[22, 'groß', 'big'], [42, 'größer', 'bigger (als …)'], [64, 'am größten', 'the biggest']])
      + T([['Adjektiv', 'Komparativ', 'Superlativ', 'Regel'], ['schön', 'schön<b>er</b>', 'am schön<b>sten</b>', 'regular'], ['schnell', 'schnell<b>er</b>', 'am schnell<b>sten</b>', 'regular'], ['lecker', 'lecker<b>er</b>', 'am lecker<b>sten</b>', 'regular'],
        ['breit', 'breit<b>er</b>', 'am breit<b>esten</b>', 'ends in -d / -t'], ['wild', 'wild<b>er</b>', 'am wild<b>esten</b>', 'ends in -d / -t'], ['hübsch', 'hübsch<b>er</b>', 'am hübsch<b>esten</b>', 'ends in -sch / -s / -z'], ['heiß', 'heiß<b>er</b>', 'am heiß<b>esten</b>', 'ends in -ß'],
        ['spannend', 'spannend<b>er</b>', 'am spannend<b>sten</b>', 'unstressed -end: no extra e'], ['dunkel', 'dunk<b>ler</b>', 'am dunkel<b>sten</b>', 'drop e (-el)'], ['teuer', 'teu<b>rer</b>', 'am teuer<b>sten</b>', 'drop e (-er after au/eu)'],
        ['alt', '<b>ä</b>lter', 'am <b>ä</b>ltesten', 'umlaut + -t'], ['gut', '<b>besser</b>', 'am <b>besten</b>', 'irregular'], ['viel', '<b>mehr</b>', 'am <b>meisten</b>', 'irregular'], ['gern', '<b>lieber</b>', 'am <b>liebsten</b>', 'irregular']]),
    examples: [{ de: 'Mein Bruder ist älter als ich.', en: 'My brother is older than me.' }, { de: 'Der Zug ist genauso schnell wie das Auto.', en: 'The train is just as fast as the car.' }, { de: 'Ich trinke am liebsten Tee.', en: 'I like tea best.' }],
    bank: [
      { p: 'Berlin ist größer ___ München.', en: 'Berlin is bigger than Munich.', o: ['als', 'wie', 'dann', 'so'], exp: 'Different → Komparativ + als.' },
      { p: 'Anna ist so alt ___ ich.', en: 'Anna is as old as me.', o: ['wie', 'als', 'wo', 'dass'], exp: 'Equal → so … wie.' },
      { p: 'Im Sommer ist es ___ als im Winter. (warm)', en: 'In summer it is warmer than in winter.', o: ['wärmer', 'warmer', 'am wärmsten', 'mehr warm'], exp: 'Short a-word → umlaut: wärmer.' },
      { p: 'Das ist das ___ Hotel in der Stadt. (teuer)', en: 'That is the most expensive hotel in town.', o: ['teuerste', 'teurerste', 'teuereste', 'teuerer'], exp: 'Superlative of teuer: der/das teuerste (the e only drops in the Komparativ: teurer).' },
      { p: 'Welcher Film war am ___? (spannend)', en: 'Which film was the most exciting?', o: ['spannendsten', 'spannendesten', 'spannendster', 'spannendeste'], exp: 'Unstressed -end → only -sten: am spannendsten.' },
      { p: 'Heute ist der ___ Tag des Jahres. (heiß)', en: 'Today is the hottest day of the year.', o: ['heißeste', 'heißste', 'heißere', 'heißten'], exp: '-ß → extra e: der heißeste Tag.' },
      { p: 'Ich spiele gern Fußball, aber ___ spiele ich Cricket.', en: 'I like playing football, but I prefer playing cricket.', o: ['lieber', 'gerner', 'mehr gern', 'am liebsten'], exp: 'gern – lieber – am liebsten.' },
      { p: 'Dein Deutsch ist viel ___ geworden! (gut)', en: 'Your German has become much better!', o: ['besser', 'guter', 'am besten', 'güter'], exp: 'gut – besser – am besten.' },
      { p: 'Der Himmel wird immer ___. (dunkel)', en: 'The sky is getting darker and darker.', o: ['dunkler', 'dunkeler', 'dünkler', 'dunkelster'], exp: '-el drops the e: dunkler.' },
      { p: 'Die Zugspitze ist der ___ Berg Deutschlands. (hoch)', en: 'The Zugspitze is Germany\'s highest mountain.', o: ['höchste', 'hochste', 'höheste', 'höherste'], exp: 'hoch – höher – am höchsten / der höchste.' },
      { p: 'Wer hat ___ Geld – du oder ich? (viel)', en: 'Who has more money – you or me?', o: ['mehr', 'vieler', 'meisten', 'mehrer'], exp: 'viel – mehr – am meisten.' }] },

  { id: 'a2_dativverben', level: 'A2', category: 'Cases', color: 'var(--blue)',
    title: 'Verben mit Dativ (helfen, gefallen, gehören …) & Dativ + Akkusativ (geben, zeigen)',
    summary: 'Some verbs take the person in the Dativ, although English uses a direct object ("help HIM" = ihm helfen). Tamil works the same: எனக்குப் பிடிக்கும் = es gefällt mir.',
    formula: '• Only Dativ: helfen, danken, gefallen, gehören, passen, schmecken, fehlen, gratulieren, antworten, glauben (jdm.), vertrauen, folgen, zuhören, wehtun, leidtun, zustimmen\n• Dativ (person) + Akkusativ (thing): geben, schenken, zeigen, bringen, erklären, schicken, leihen, empfehlen, sagen, kaufen\n• Order: two nouns → Dativ before Akkusativ (Ich gebe dem Kind den Ball) · Akkusativ PRONOUN first (Ich gebe ihn dem Kind / Ich gebe ihn ihm)\n• "Es gefällt mir / schmeckt mir / tut mir weh / tut mir leid" — the thing is the subject, the person is Dativ',
    tableHTML: T([['Verb', 'Example', 'Tamil (same idea)'], ['gefallen', 'Die Stadt <b>gefällt mir</b>.', 'எனக்கு நகரம் பிடிக்கும்'], ['helfen', 'Ich <b>helfe dir</b>.', 'நான் உனக்கு உதவுகிறேன்'], ['gehören', 'Das Buch <b>gehört ihm</b>.', 'புத்தகம் அவனுக்குச் சொந்தம்'],
      ['schmecken', 'Das Essen <b>schmeckt uns</b>.', 'எங்களுக்கு உணவு ருசிக்கிறது'], ['wehtun', 'Der Kopf <b>tut mir weh</b>.', 'எனக்குத் தலை வலிக்கிறது'], ['geben (D + A)', 'Ich gebe <b>dem Kind den Ball</b>.', 'நான் குழந்தைக்குப் பந்தைக் கொடுக்கிறேன்']]),
    examples: [{ de: 'Kann ich Ihnen helfen?', en: 'Can I help you?' }, { de: 'Ich danke dir für die Blumen.', en: 'Thank you for the flowers.' }, { de: 'Er zeigt seiner Frau die Fotos.', en: 'He shows his wife the photos.' }],
    bank: [
      { p: 'Ich helfe ___ Nachbarin.', en: 'I help the (female) neighbour.', o: ['der', 'die', 'den', 'dem'], exp: 'helfen + Dativ; feminine Dativ → der.' },
      { p: 'Die Jacke gefällt ___ sehr. (ich)', en: 'I really like the jacket.', o: ['mir', 'mich', 'ich', 'mein'], exp: 'gefallen + Dativ: mir.' },
      { p: 'Wem gehört das Fahrrad? – Es gehört ___ Bruder.', en: 'Whose is the bike? – It belongs to my brother.', o: ['meinem', 'meinen', 'mein', 'meiner'], exp: 'gehören + Dativ masculine → meinem.' },
      { p: 'Wir gratulieren ___ zum Geburtstag! (du)', en: 'Happy birthday! (We congratulate you.)', o: ['dir', 'dich', 'du', 'dein'], exp: 'gratulieren + Dativ → dir.' },
      { p: 'Ich schenke ___ Mutter einen Schal.', en: 'I give my mother a scarf.', o: ['meiner', 'meine', 'meinen', 'meinem'], exp: 'Person = Dativ, feminine → meiner.' },
      { p: 'Hast du das Buch? – Ja, ich gebe ___ dir morgen.', en: 'Do you have the book? – Yes, I\'ll give it to you tomorrow.', o: ['es', 'ihm', 'ihn', 'sie'], exp: 'das Buch → es (Akk.); Akkusativ pronoun comes first.' },
      { p: 'Das Essen schmeckt ___ Kindern nicht.', en: 'The children don\'t like the food.', o: ['den', 'die', 'der', 'dem'], exp: 'Dativ plural → den Kindern.' },
      { p: 'Entschuldigung, das tut ___ leid!', en: 'Sorry, I\'m sorry about that!', o: ['mir', 'mich', 'ich', 'mein'], exp: 'leidtun + Dativ → mir.' },
      { p: 'Kannst du ___ den Weg erklären? (ich)', en: 'Can you explain the way to me?', o: ['mir', 'mich', 'meinen', 'ich'], exp: 'erklären: person in Dativ → mir.' }] },

  { id: 'a2_verben_praep', level: 'A2', category: 'Prepositions', color: 'var(--green)',
    title: 'Verben & Adjektive mit festen Präpositionen (warten auf, stolz auf …)',
    summary: 'Many verbs and adjectives come with a fixed preposition that you must learn together — the preposition often differs from English (warten AUF = wait FOR). Learn them as one block.',
    formula: '• Learn verb + preposition + case together: warten auf + A, denken an + A, sich freuen auf + A (future) / über + A (now/past)\n• Question: thing → wo(r)+preposition (Worauf wartest du?) · person → preposition + wen/wem (Auf wen wartest du?)\n• Answer with da(r)+preposition for things: Ich warte darauf. (see rule "Da- & Wo-Komposita")',
    tableHTML: T([['Verb / Adjektiv', 'Präp. + Fall', 'Beispiel'], ['warten', 'auf + A', 'Ich warte <b>auf den</b> Bus.'], ['denken', 'an + A', 'Ich denke <b>an dich</b>.'], ['sich freuen', 'auf + A / über + A', 'Ich freue mich <b>auf den</b> Urlaub / <b>über das</b> Geschenk.'],
      ['sich interessieren', 'für + A', 'Er interessiert sich <b>für</b> Musik.'], ['sprechen', 'mit + D / über + A', 'Ich spreche <b>mit dem</b> Chef <b>über die</b> Arbeit.'], ['träumen', 'von + D', 'Sie träumt <b>von einem</b> Haus.'],
      ['Angst haben', 'vor + D', 'Er hat Angst <b>vor dem</b> Hund.'], ['teilnehmen', 'an + D', 'Ich nehme <b>am</b> Kurs teil.'], ['sich kümmern', 'um + A', 'Sie kümmert sich <b>um die</b> Kinder.'], ['sich erinnern', 'an + A', 'Ich erinnere mich <b>an den</b> Tag.'],
      ['bitten', 'um + A', 'Ich bitte dich <b>um</b> Hilfe.'], ['sich bewerben', 'um + A / bei + D', 'Ich bewerbe mich <b>um die</b> Stelle <b>bei</b> Siemens.'], ['stolz', 'auf + A', 'Ich bin stolz <b>auf dich</b>.'], ['zufrieden', 'mit + D', 'Er ist zufrieden <b>mit dem</b> Ergebnis.'],
      ['interessiert', 'an + D', 'Ich bin <b>an dem</b> Job interessiert.'], ['verheiratet', 'mit + D', 'Sie ist <b>mit einem</b> Arzt verheiratet.'], ['abhängig', 'von + D', 'Das ist <b>vom</b> Wetter abhängig.']]),
    examples: [{ de: 'Ich freue mich schon auf das Wochenende.', en: 'I\'m already looking forward to the weekend.' }, { de: 'Worüber sprecht ihr?', en: 'What are you talking about?' }, { de: 'Wir sind sehr stolz auf unsere Tochter.', en: 'We are very proud of our daughter.' }],
    bank: [
      { p: 'Ich warte schon seit 20 Minuten ___ den Bus.', en: 'I have been waiting for the bus for 20 minutes.', o: ['auf', 'für', 'an', 'um'], exp: 'warten auf + Akkusativ.' },
      { p: 'Er interessiert sich sehr ___ Fußball.', en: 'He is very interested in football.', o: ['für', 'an', 'auf', 'über'], exp: 'sich interessieren für + A.' },
      { p: 'Ich denke oft ___ meine Familie in Indien.', en: 'I often think of my family in India.', o: ['an', 'über', 'von', 'auf'], exp: 'denken an + A.' },
      { p: 'Die Kinder freuen sich ___ die Ferien. (they are coming)', en: 'The children are looking forward to the holidays.', o: ['auf', 'über', 'für', 'an'], exp: 'Looking forward (future) → sich freuen auf.' },
      { p: 'Sie hat Angst ___ Spinnen.', en: 'She is afraid of spiders.', o: ['vor', 'von', 'für', 'um'], exp: 'Angst haben vor + D.' },
      { p: 'Ich bin sehr zufrieden ___ meiner neuen Wohnung.', en: 'I am very happy with my new flat.', o: ['mit', 'über', 'von', 'für'], exp: 'zufrieden mit + D.' },
      { p: 'Wer kümmert sich ___ den Hund?', en: 'Who takes care of the dog?', o: ['um', 'für', 'auf', 'an'], exp: 'sich kümmern um + A.' },
      { p: 'Morgen nehme ich ___ Deutschkurs teil.', en: 'Tomorrow I\'m taking part in the German course.', o: ['am', 'im', 'beim', 'zum'], exp: 'teilnehmen an + D: an dem → am.' },
      { p: '___ wartest du? – Auf meine Freundin.', en: 'Who are you waiting for? – For my girlfriend.', o: ['Auf wen', 'Worauf', 'Wofür', 'Auf was'], exp: 'Person → preposition + wen.' },
      { p: 'Die Eltern sind stolz ___ ihren Sohn.', en: 'The parents are proud of their son.', o: ['auf', 'über', 'von', 'an'], exp: 'stolz auf + A.' }] },

  { id: 'a2_zeit_ort', level: 'A2', category: 'Prepositions', color: 'var(--purple)',
    title: 'Zeit- & Ortsangaben: seit, vor, nach, ab · nach, zu, in, bei, aus',
    summary: 'Small words, big difference: "vor zwei Jahren" = two years AGO, "seit zwei Jahren" = FOR two years (still true now). For places: countries/cities → nach, people and shops → zu, inside → in, at someone\'s place → bei.',
    formula: '• seit + D: started in the past, still going → Ich wohne seit 2 Jahren hier. (Präsens!)\n• vor + D: ago → Ich bin vor 2 Jahren gekommen. · nach + D: after → nach dem Essen · ab: from … on → ab Montag\n• in + D (in the future): in zwei Tagen · von … bis: von 9 bis 17 Uhr · während + G: während des Kurses\n• Where to? nach + city/country without article (nach Berlin, nach Indien) · in + country WITH article (in die Schweiz, in die USA) · zu + person/shop/event (zum Arzt, zu Oma) · in + building you enter (ins Kino) · nach Hause\n• Where? in (in Berlin) · bei + person/company (bei Oma, bei Siemens) · zu Hause · Where from? aus (aus Indien, aus dem Haus) · von (vom Arzt, von der Arbeit)',
    tableHTML: T([['Wohin?', 'Wo?', 'Woher?'], ['<b>nach</b> Berlin / Indien', '<b>in</b> Berlin / Indien', '<b>aus</b> Berlin / Indien'], ['<b>in die</b> Schweiz / Türkei', '<b>in der</b> Schweiz', '<b>aus der</b> Schweiz'], ['<b>zum</b> Arzt / <b>zu</b> Oma', '<b>beim</b> Arzt / <b>bei</b> Oma', '<b>vom</b> Arzt / <b>von</b> Oma'],
      ['<b>ins</b> Kino / <b>in die</b> Stadt', '<b>im</b> Kino / <b>in der</b> Stadt', '<b>aus dem</b> Kino'], ['<b>nach</b> Hause', '<b>zu</b> Hause', '<b>von</b> zu Hause']])
      + T([['Zeit', 'Bedeutung', 'Beispiel'], ['seit + D', 'since / for (still now)', 'Ich lerne <b>seit</b> einem Jahr Deutsch.'], ['vor + D', 'ago', 'Ich bin <b>vor</b> einem Jahr gekommen.'], ['nach + D', 'after', '<b>Nach</b> der Arbeit gehe ich einkaufen.'], ['in + D', 'in (future)', 'Der Zug kommt <b>in</b> zehn Minuten.'], ['ab', 'from … on', '<b>Ab</b> Montag habe ich Urlaub.']]),
    examples: [{ de: 'Ich wohne seit drei Jahren in Deutschland.', en: 'I have been living in Germany for three years.' }, { de: 'Am Samstag fahre ich zu meiner Tante nach Köln.', en: 'On Saturday I\'m going to my aunt\'s in Cologne.' }, { de: 'Er arbeitet bei Bosch.', en: 'He works at Bosch.' }],
    bank: [
      { p: 'Ich lerne ___ sechs Monaten Deutsch.', en: 'I have been learning German for six months.', o: ['seit', 'vor', 'ab', 'für'], exp: 'Still going on → seit + Dativ (with Präsens).' },
      { p: 'Ich bin ___ zwei Jahren nach Deutschland gekommen.', en: 'I came to Germany two years ago.', o: ['vor', 'seit', 'nach', 'in'], exp: 'ago → vor + Dativ.' },
      { p: 'Im Sommer fliegen wir ___ Indien.', en: 'In summer we fly to India.', o: ['nach', 'in', 'zu', 'bei'], exp: 'Country without article → nach.' },
      { p: 'Nächstes Jahr fahren wir ___ Schweiz.', en: 'Next year we are going to Switzerland.', o: ['in die', 'nach', 'zur', 'in der'], exp: 'Country WITH article (die Schweiz) → in die.' },
      { p: 'Ich muss heute ___ Zahnarzt.', en: 'I have to go to the dentist today.', o: ['zum', 'beim', 'nach', 'ins'], exp: 'To a person/practice → zu + dem = zum.' },
      { p: 'Ich war gestern ___ Zahnarzt.', en: 'I was at the dentist yesterday.', o: ['beim', 'zum', 'im', 'am'], exp: 'At someone\'s place → bei + dem = beim.' },
      { p: 'Nach der Arbeit gehe ich ___ Hause.', en: 'After work I go home.', o: ['nach', 'zu', 'in', 'bei'], exp: 'Going home = nach Hause (being home = zu Hause).' },
      { p: 'Der Bus kommt ___ fünf Minuten.', en: 'The bus is coming in five minutes.', o: ['in', 'nach', 'seit', 'vor'], exp: 'Future time span → in + Dativ.' },
      { p: 'Woher kommst du? – ___ Tamil Nadu.', en: 'Where are you from? – From Tamil Nadu.', o: ['Aus', 'Von', 'Nach', 'In'], exp: 'Origin (region/country) → aus.' },
      { p: 'Meine Schwester arbeitet ___ einer Bank.', en: 'My sister works at a bank.', o: ['bei', 'zu', 'an', 'nach'], exp: 'Employer → bei.' }] },

  { id: 'a2_pronomen2', level: 'A2', category: 'Pronouns', color: 'var(--gold)',
    title: 'man, jemand, niemand, etwas, nichts · dieser · es gibt · es',
    summary: 'Useful little words: man (one/you in general), jemand/niemand (somebody/nobody), etwas/nichts (something/nothing), dieser (this), es gibt + Akkusativ (there is/are) and "es" as an empty subject (Es regnet).',
    formula: '• man + er-form: In Deutschland isst man um 12 Uhr. (never "man" + plural)\n• jemand (somebody) · niemand (nobody) · etwas (something) · nichts (nothing) · alle (all) · viele (many) · einige (some)\n• dieser / diese / dieses = this (endings like der/die/das): dieser Mann, diesen Mann, diesem Mann\n• es gibt + Akkusativ = there is/are: Es gibt einen Park. Gibt es hier ein Café?\n• es as empty subject: Es regnet. Es ist kalt. Es ist 8 Uhr. Wie geht es dir?',
    tableHTML: T([['Wort', 'Bedeutung', 'Beispiel'], ['man', 'one / you (general)', 'Hier <b>darf man</b> nicht parken.'], ['jemand / niemand', 'somebody / nobody', 'Ist <b>jemand</b> da? – Nein, <b>niemand</b>.'], ['etwas / nichts', 'something / nothing', 'Möchtest du <b>etwas</b> trinken? – Nein, <b>nichts</b>.'],
      ['dieser / diese / dieses', 'this', '<b>Diese</b> Jacke ist schön. Ich nehme <b>diesen</b> Rock.'], ['es gibt + Akk.', 'there is / are', 'In der Stadt <b>gibt es einen</b> Zoo.'], ['es (empty)', 'it (weather, time …)', '<b>Es</b> regnet. <b>Es</b> ist spät.']]),
    examples: [{ de: 'Wie sagt man das auf Deutsch?', en: 'How do you say that in German?' }, { de: 'Gibt es hier in der Nähe eine Apotheke?', en: 'Is there a pharmacy near here?' }, { de: 'Hat jemand meinen Schlüssel gesehen?', en: 'Has anybody seen my key?' }],
    bank: [
      { p: 'In Deutschland ___ man viel Brot.', en: 'In Germany people eat a lot of bread.', o: ['isst', 'essen', 'esst', 'esse'], exp: 'man + er-form: man isst.' },
      { p: 'Im Park gibt es ___ großen See.', en: 'There is a big lake in the park.', o: ['einen', 'ein', 'einem', 'eine'], exp: 'es gibt + Akkusativ: der See → einen.' },
      { p: 'Ist ___ zu Hause? – Nein, niemand.', en: 'Is anybody home? – No, nobody.', o: ['jemand', 'niemand', 'etwas', 'man'], exp: 'somebody/anybody = jemand.' },
      { p: 'Ich habe ___ gegessen. Ich habe Hunger!', en: 'I haven\'t eaten anything. I\'m hungry!', o: ['nichts', 'niemand', 'nicht', 'kein'], exp: 'nothing = nichts.' },
      { p: 'Wie findest du ___ Kleid?', en: 'How do you like this dress?', o: ['dieses', 'dieser', 'diesen', 'diese'], exp: 'das Kleid, Akk. → dieses.' },
      { p: 'Mit ___ Bus fährst du? – Mit dem 12er.', en: 'Which bus do you take? – The number 12.', o: ['welchem', 'welchen', 'welcher', 'welches'], exp: 'mit + Dativ, der Bus → welchem.' },
      { p: '___ regnet schon den ganzen Tag.', en: 'It has been raining all day.', o: ['Es', 'Das', 'Er', 'Man'], exp: 'Weather verbs use es.' },
      { p: 'Möchtest du ___ trinken?', en: 'Would you like something to drink?', o: ['etwas', 'jemand', 'nichts', 'man'], exp: 'something = etwas.' }] },

  { id: 'a2_wortbildung', level: 'A2', category: 'Vocabulary', color: 'var(--green)',
    title: 'Wortbildung: Komposita & Endungen (die Haustür · -ung · -heit · -chen)',
    summary: 'German builds long words from short ones. The LAST part decides the article and the meaning: das Haus + die Tür = die Haustür. Many endings tell you the article for sure.',
    formula: '• Compound: last word = main word + article: die Küche + der Tisch = der Küchentisch · die Kinder + der Garten = der Kindergarten\n• Always die: -ung, -heit, -keit, -schaft, -ion, -tät, -ei, -ik (die Wohnung, die Freiheit, die Möglichkeit)\n• Always das: -chen, -lein (small), -ment, -um (das Mädchen, das Brötchen, das Zentrum) · infinitive as noun: das Essen\n• Usually der: -er (person/tool: der Lehrer, der Drucker), -ling, -ismus · -in = female: die Lehrerin\n• Adjectives: un- (not): unmöglich · -bar (can be done): essbar · -los (without): arbeitslos · -lich / -ig: freundlich, sonnig',
    tableHTML: T([['Teile', 'Wort', 'Bedeutung'], ['das Haus + die Tür', '<b>die</b> Haus<b>tür</b>', 'front door'], ['die Küche + der Tisch', '<b>der</b> Küchen<b>tisch</b>', 'kitchen table'], ['schlafen + das Zimmer', '<b>das</b> Schlaf<b>zimmer</b>', 'bedroom'],
      ['wohnen + -ung', '<b>die</b> Wohn<b>ung</b>', 'flat'], ['frei + -heit', '<b>die</b> Frei<b>heit</b>', 'freedom'], ['das Brot + -chen', '<b>das</b> Bröt<b>chen</b>', 'bread roll'], ['lehren + -er / -in', '<b>der</b> Lehr<b>er</b> / <b>die</b> Lehrer<b>in</b>', 'teacher'], ['un- + möglich', 'unmöglich', 'impossible']]),
    examples: [{ de: 'Die Haustür ist offen.', en: 'The front door is open.' }, { de: 'Das Mädchen liest die Zeitung.', en: 'The girl reads the newspaper. (das Mädchen: -chen!)' }, { de: 'Das ist leider unmöglich.', en: 'Unfortunately that is impossible.' }],
    bank: [
      { p: '___ Kühlschrank ist leer. (kühl + der Schrank)', en: 'The fridge is empty.', o: ['der', 'die', 'das', 'den'], exp: 'Last part der Schrank → der Kühlschrank.' },
      { p: '___ Wohnung ist groß.', en: 'The flat is big.', o: ['Die', 'Der', 'Das', 'Den'], exp: '-ung is always die.' },
      { p: '___ Mädchen spielt im Garten.', en: 'The girl is playing in the garden.', o: ['Das', 'Die', 'Der', 'Den'], exp: '-chen is always das (even for a girl).' },
      { p: '___ Freundlichkeit der Leute hat mir gefallen.', en: 'I liked the friendliness of the people.', o: ['Die', 'Das', 'Der', 'Den'], exp: '-keit is always die.' },
      { p: '___ Haustür ist kaputt.', en: 'The front door is broken.', o: ['Die', 'Das', 'Der', 'Den'], exp: 'Last part die Tür → die Haustür.' },
      { p: 'Das Wasser kann man trinken. Es ist ___.', en: 'You can drink the water. It is drinkable.', o: ['trinkbar', 'trinklos', 'untrinkbar', 'trinklich'], exp: '-bar = can be done.' },
      { p: 'Er hat keine Arbeit. Er ist ___.', en: 'He has no work. He is unemployed.', o: ['arbeitslos', 'arbeitsbar', 'unarbeit', 'arbeitlich'], exp: '-los = without.' },
      { p: '___ Zeitung liegt auf dem Tisch.', en: 'The newspaper is on the table.', o: ['Die', 'Der', 'Das', 'Den'], exp: '-ung → die Zeitung.' }] },

  /* ============================ B1 ============================ */
  { id: 'b1_plusquam_futur', level: 'B1', category: 'Tenses', color: 'var(--red)',
    title: 'Plusquamperfekt & Futur I (hatte gegessen · werde fahren)',
    summary: 'Plusquamperfekt = the past before the past (hatte/war + Partizip II), typical after "nachdem". Futur I = werden + infinitive for plans, promises and guesses. Tamil: வந்திருந்தான் = er war gekommen.',
    formula: '• Plusquamperfekt: hatte / war (Präteritum of haben/sein) + Partizip II → Ich hatte schon gegessen, als er kam.\n• Same haben/sein choice as in the Perfekt: Er war schon gegangen.\n• nachdem + Plusquamperfekt, main clause Präteritum/Perfekt: Nachdem ich gegessen hatte, ging ich spazieren.\n• Futur I: werden (pos. 2) + infinitive (end) → Ich werde nächstes Jahr heiraten. · guess: Er wird krank sein. (= probably)\n• For plans, German often uses Präsens + time word: Morgen fahre ich nach Köln.',
    tableHTML: T([['', 'Plusquamperfekt', 'Futur I'], ['ich', '<b>hatte</b> gearbeitet / <b>war</b> gefahren', '<b>werde</b> arbeiten'], ['du', 'hattest … / warst …', 'wirst arbeiten'], ['er/sie/es', 'hatte … / war …', '<b>wird</b> arbeiten'], ['wir', 'hatten … / waren …', 'werden arbeiten'], ['ihr', 'hattet … / wart …', 'werdet arbeiten'], ['sie/Sie', 'hatten … / waren …', 'werden arbeiten']]),
    examples: [{ de: 'Als ich am Bahnhof ankam, war der Zug schon abgefahren.', en: 'When I arrived at the station, the train had already left.' }, { de: 'Nachdem er die Prüfung bestanden hatte, feierte er.', en: 'After he had passed the exam, he celebrated.' }, { de: 'Ich werde dich morgen anrufen.', en: 'I will call you tomorrow.' }],
    bank: [
      { p: 'Als wir ankamen, ___ der Film schon begonnen.', en: 'When we arrived, the film had already started.', o: ['hatte', 'war', 'hat', 'ist'], exp: 'Past before the past → Plusquamperfekt; beginnen uses haben → hatte begonnen.' },
      { p: 'Nachdem sie nach Deutschland gekommen ___, lernte sie Deutsch.', en: 'After she had come to Germany, she learned German.', o: ['war', 'hatte', 'ist', 'wurde'], exp: 'kommen uses sein → war gekommen.' },
      { p: 'Nächstes Jahr ___ ich meine Familie in Indien besuchen.', en: 'Next year I will visit my family in India.', o: ['werde', 'wird', 'würde', 'wurde'], exp: 'Futur I: ich werde + infinitive.' },
      { p: 'Er ist nicht gekommen. Er ___ wohl krank sein.', en: 'He didn\'t come. He is probably ill.', o: ['wird', 'wurde', 'würde', 'werde'], exp: 'Futur I for a guess: er wird … sein.' },
      { p: 'Ich hatte den Schlüssel ___, deshalb konnte ich nicht rein.', en: 'I had forgotten the key, so I couldn\'t get in.', o: ['vergessen', 'vergesst', 'gevergessen', 'vergaß'], exp: 'Plusquamperfekt: hatte + Partizip II (vergessen).' },
      { p: '___ du mir helfen? – Ja, ich werde dir helfen.', en: 'Will you help me? – Yes, I will help you.', o: ['Wirst', 'Wird', 'Werdest', 'Wurdest'], exp: 'du → wirst.' },
      { p: 'Nachdem wir gegessen ___, gingen wir spazieren.', en: 'After we had eaten, we went for a walk.', o: ['hatten', 'waren', 'haben', 'sind'], exp: 'essen uses haben → hatten gegessen.' }] },

  { id: 'b1_konj2_vergangenheit', level: 'B1', category: 'Moods', color: 'var(--purple)',
    title: 'Konjunktiv II der Vergangenheit (hätte gemacht · wäre gekommen)',
    summary: 'For things that did NOT happen in the past: regrets, missed chances, "if I had …". hätte/wäre + Partizip II. Tamil has exactly this form: வந்திருந்தால் … வந்திருப்பேன்.',
    formula: '• hätte / wäre + Partizip II (same haben/sein choice as the Perfekt)\n• Wenn ich Zeit gehabt hätte, wäre ich gekommen. (unreal condition in the past)\n• Regret / wish: Ich hätte mehr lernen sollen. Hätte ich das nur gewusst!\n• With a modal verb: hätte + infinitive + modal infinitive (end) → Ich hätte dir helfen können.\n• Reproach: Du hättest mich anrufen sollen!',
    tableHTML: T([['Present unreal (rule 5)', 'Past unreal (this rule)'], ['Wenn ich Zeit <b>hätte</b>, <b>würde</b> ich kommen.', 'Wenn ich Zeit <b>gehabt hätte</b>, <b>wäre</b> ich <b>gekommen</b>.'], ['Ich <b>würde</b> dir helfen.', 'Ich <b>hätte</b> dir <b>geholfen</b>.'], ['Ich <b>könnte</b> dir helfen.', 'Ich <b>hätte</b> dir <b>helfen können</b>.'], ['Du <b>solltest</b> mehr schlafen.', 'Du <b>hättest</b> mehr <b>schlafen sollen</b>.']]),
    examples: [{ de: 'Wenn ich das gewusst hätte, wäre ich früher gekommen.', en: 'If I had known that, I would have come earlier.' }, { de: 'Ich hätte gern Medizin studiert.', en: 'I would have liked to study medicine.' }, { de: 'Du hättest mich fragen können.', en: 'You could have asked me.' }],
    bank: [
      { p: 'Wenn ich früher aufgestanden ___, hätte ich den Zug erreicht.', en: 'If I had got up earlier, I would have caught the train.', o: ['wäre', 'hätte', 'würde', 'war'], exp: 'aufstehen uses sein → wäre aufgestanden.' },
      { p: 'Wenn du mich gefragt ___, hätte ich dir geholfen.', en: 'If you had asked me, I would have helped you.', o: ['hättest', 'wärst', 'würdest', 'hattest'], exp: 'fragen uses haben → hättest gefragt.' },
      { p: 'Ich ___ gern mitgekommen, aber ich war krank.', en: 'I would have liked to come along, but I was ill.', o: ['wäre', 'hätte', 'würde', 'war'], exp: 'mitkommen = movement → wäre mitgekommen.' },
      { p: 'Du hättest mich anrufen ___!', en: 'You should have called me!', o: ['sollen', 'gesollt', 'sollten', 'soll'], exp: 'Modal in the past Konj. II: hätte + infinitive + modal infinitive (sollen).' },
      { p: 'Hätte ich das nur ___!', en: 'If only I had known that!', o: ['gewusst', 'gewisst', 'wusste', 'wissen'], exp: 'hätte + Partizip II of wissen = gewusst.' },
      { p: 'Wir hätten den Termin fast ___. (vergessen)', en: 'We would almost have forgotten the appointment.', o: ['vergessen', 'vergaßen', 'vergessten', 'gevergessen'], exp: 'Partizip II: vergessen.' }] },

  { id: 'b1_lassen', level: 'B1', category: 'Verbs', color: 'var(--gold)',
    title: 'lassen (Ich lasse mein Auto reparieren)',
    summary: 'lassen has three main meanings: have something done by someone else, let/allow, and leave something somewhere. Tamil has the same "have done" form with வை: பழுது பார்க்க வைக்கிறேன்.',
    formula: '• have something done: lassen + infinitive → Ich lasse mir die Haare schneiden. Er lässt sein Auto reparieren.\n• let / allow: Lass mich das machen! Meine Eltern lassen mich nicht allein reisen.\n• leave (somewhere): Ich habe mein Handy zu Hause gelassen.\n• Präsens: ich lasse, du lässt, er lässt · Perfekt with an infinitive: hat … reparieren lassen (double infinitive!)\n• sich lassen = can be done: Das lässt sich leicht erklären.',
    tableHTML: T([['Bedeutung', 'Beispiel', 'English'], ['have done', 'Ich <b>lasse</b> mein Fahrrad <b>reparieren</b>.', 'I\'m having my bike repaired.'], ['let', '<b>Lass</b> mich bitte ausreden!', 'Please let me finish!'], ['leave', 'Ich habe den Schirm im Bus <b>gelassen</b>.', 'I left the umbrella on the bus.'],
      ['Perfekt (+ Inf.)', 'Ich habe mein Auto <b>reparieren lassen</b>.', 'I had my car repaired.'], ['sich lassen', 'Das Fenster <b>lässt sich</b> nicht öffnen.', 'The window can\'t be opened.']]),
    examples: [{ de: 'Wo lässt du dir die Haare schneiden?', en: 'Where do you get your hair cut?' }, { de: 'Lass uns ins Kino gehen!', en: 'Let\'s go to the cinema!' }, { de: 'Ich habe meine Brille zu Hause gelassen.', en: 'I left my glasses at home.' }],
    bank: [
      { p: 'Ich repariere mein Auto nicht selbst. Ich ___ es reparieren.', en: 'I don\'t repair my car myself. I have it repaired.', o: ['lasse', 'lässt', 'lass', 'gelassen'], exp: 'ich lasse + infinitive = have done.' },
      { p: 'Er ___ sich jeden Monat die Haare schneiden.', en: 'He gets his hair cut every month.', o: ['lässt', 'lasst', 'lasse', 'lassen'], exp: 'er lässt (a → ä).' },
      { p: 'Ich habe mein Handy im Büro ___.', en: 'I left my phone at the office.', o: ['gelassen', 'lassen', 'gelasst', 'ließ'], exp: 'leave something = lassen, Perfekt without another infinitive → gelassen.' },
      { p: 'Wir haben die Wohnung streichen ___.', en: 'We had the flat painted.', o: ['lassen', 'gelassen', 'lässt', 'ließen'], exp: 'With another infinitive → double infinitive: streichen lassen.' },
      { p: '___ mich bitte in Ruhe!', en: 'Please leave me alone!', o: ['Lass', 'Lässt', 'Lasse', 'Lassen'], exp: 'du-imperative: Lass!' },
      { p: 'Das Problem ___ sich leicht lösen.', en: 'The problem can easily be solved.', o: ['lässt', 'lasst', 'lassen', 'ließt'], exp: 'sich lassen = can be done; das Problem → lässt.' }] },

  { id: 'b1_modalpartikeln', level: 'B1', category: 'Spoken German', color: 'var(--green)',
    title: 'Modalpartikeln: doch, mal, ja, eben / halt, denn, schon',
    summary: 'Tiny words that add feeling — friendlier, more surprised, more certain. They cannot be translated word for word, but natives use them all the time. Tamil does something similar with -தான், -ஏ, -ஆ.',
    formula: '• mal: softens a request → Komm mal her! Kannst du mal helfen?\n• doch: urges / reminds → Komm doch mit! Das weißt du doch!\n• ja: shared knowledge / surprise → Das ist ja toll! Du weißt ja, dass …\n• denn: interest in questions → Wo warst du denn? Was ist denn los?\n• eben / halt: that\'s how it is → Das ist eben so. Dann gehen wir halt zu Fuß.\n• schon: reassurance → Das schaffst du schon!',
    tableHTML: T([['Partikel', 'Wirkung', 'Beispiel'], ['mal', 'softer request', 'Kannst du <b>mal</b> das Fenster aufmachen?'], ['doch', 'urging / "come on"', 'Setz dich <b>doch</b>!'], ['ja', 'surprise / "as you know"', 'Du bist <b>ja</b> schon da!'], ['denn', 'curious question', 'Was machst du <b>denn</b> hier?'], ['eben / halt', 'can\'t be changed', 'Der Bus ist weg. Dann laufen wir <b>halt</b>.'], ['schon', 'reassuring', 'Keine Sorge, das klappt <b>schon</b>.']]),
    examples: [{ de: 'Hör mal!', en: 'Listen! (friendly)' }, { de: 'Das ist ja interessant!', en: 'Oh, that\'s interesting!' }, { de: 'Wie heißt du denn?', en: 'So, what\'s your name?' }],
    bank: [
      { p: 'Kannst du ___ kurz warten?', en: 'Can you wait a moment?', o: ['mal', 'denn', 'ja', 'eben'], exp: 'mal softens a request.' },
      { p: 'Was ist ___ los? Du siehst traurig aus.', en: 'What\'s wrong? You look sad.', o: ['denn', 'mal', 'doch', 'halt'], exp: 'denn in a question shows interest.' },
      { p: 'Komm ___ mit! Das wird bestimmt lustig.', en: 'Do come along! It\'ll be fun.', o: ['doch', 'mal', 'denn', 'schon'], exp: 'doch urges: Komm doch mit!' },
      { p: 'Keine Angst, du schaffst das ___!', en: 'Don\'t worry, you\'ll manage!', o: ['schon', 'denn', 'mal', 'ja'], exp: 'schon reassures.' },
      { p: 'Das Wetter ist schlecht. Das ist ___ so in Deutschland.', en: 'The weather is bad. That\'s just how it is in Germany.', o: ['eben', 'denn', 'mal', 'doch'], exp: 'eben/halt = that\'s the way it is.' },
      { p: 'Oh, du hast ___ ein neues Auto!', en: 'Oh, you have a new car!', o: ['ja', 'denn', 'mal', 'halt'], exp: 'ja expresses surprise.' }] },

  { id: 'b1_zustandspassiv', level: 'B1', category: 'Voice', color: 'var(--blue)',
    title: 'Zustandspassiv: sein + Partizip II (Die Tür ist geöffnet)',
    summary: 'The normal passive (werden + Partizip II) describes an ACTION. The Zustandspassiv (sein + Partizip II) describes the RESULT — the state after the action.',
    formula: '• Vorgangspassiv (action): Die Tür wird geöffnet. (someone is opening it now)\n• Zustandspassiv (state): Die Tür ist geöffnet. (it is open)\n• Past: Die Tür war geöffnet. · Typical: geöffnet/geschlossen (shops), reserviert, verletzt, verheiratet, gebucht, erledigt, geputzt',
    tableHTML: T([['Vorgang (werden)', 'Zustand (sein)'], ['Der Tisch <b>wird</b> reserviert.', 'Der Tisch <b>ist</b> reserviert.'], ['Das Geschäft <b>wird</b> um 20 Uhr geschlossen.', 'Das Geschäft <b>ist</b> geschlossen.'], ['Die Arbeit <b>wird</b> erledigt.', 'Die Arbeit <b>ist</b> erledigt.'], ['Das Zimmer <b>wurde</b> geputzt.', 'Das Zimmer <b>war</b> geputzt.']]),
    examples: [{ de: 'Die Bank ist heute geschlossen.', en: 'The bank is closed today.' }, { de: 'Der Tisch ist leider schon reserviert.', en: 'Unfortunately the table is already reserved.' }, { de: 'Ist das Formular schon ausgefüllt?', en: 'Is the form already filled in?' }],
    bank: [
      { p: 'Am Sonntag ___ die Geschäfte geschlossen.', en: 'On Sunday the shops are closed.', o: ['sind', 'werden', 'haben', 'wurden'], exp: 'State (they are closed) → sein.' },
      { p: 'Der Brief ___ gerade geschrieben.', en: 'The letter is being written right now.', o: ['wird', 'ist', 'hat', 'war'], exp: 'Action in progress → werden.' },
      { p: 'Keine Sorge, alles ___ schon erledigt.', en: 'Don\'t worry, everything is already done.', o: ['ist', 'wird', 'hat', 'werden'], exp: 'Result/state → sein.' },
      { p: 'Als ich ankam, ___ das Fenster geöffnet.', en: 'When I arrived, the window was open.', o: ['war', 'wurde', 'hatte', 'ist'], exp: 'State in the past → war.' },
      { p: 'Das Haus ___ 1990 gebaut.', en: 'The house was built in 1990.', o: ['wurde', 'war', 'ist', 'hat'], exp: 'Action (building it) → wurde.' }] },

  { id: 'b1_nomen_verb', level: 'B1', category: 'Vocabulary', color: 'var(--purple)',
    title: 'Nomen-Verb-Verbindungen (eine Entscheidung treffen …)',
    summary: 'Fixed pairs of noun + verb, very common in official letters, work and exams. The verb is often not the one you expect (a decision is "met": treffen) — learn them as one block.',
    formula: '• eine Entscheidung treffen (= entscheiden) · eine Frage stellen (= fragen) · einen Antrag stellen (= beantragen)\n• zur Verfügung stehen (= be available) · in Frage kommen (= be possible) · Bescheid sagen/geben (= inform)\n• Rücksicht nehmen auf + A (= consider) · eine Rolle spielen (= matter) · in Kraft treten (law: come into force)\n• zum Ausdruck bringen (= express) · Kritik üben an + D (= criticise) · Abschied nehmen von + D (= say goodbye)',
    tableHTML: T([['Nomen-Verb', 'Bedeutung', 'Beispiel'], ['eine Entscheidung <b>treffen</b>', 'decide', 'Wir müssen bald eine Entscheidung treffen.'], ['einen Antrag <b>stellen</b>', 'apply (officially)', 'Ich habe einen Antrag auf Kindergeld gestellt.'], ['Bescheid <b>sagen</b>', 'let someone know', 'Sag mir bitte Bescheid!'],
      ['zur Verfügung <b>stehen</b>', 'be available', 'Der Raum steht Ihnen zur Verfügung.'], ['in Frage <b>kommen</b>', 'be an option', 'Das kommt nicht in Frage!'], ['Rücksicht <b>nehmen</b> auf', 'be considerate of', 'Bitte nehmen Sie Rücksicht auf die Nachbarn.'], ['eine Rolle <b>spielen</b>', 'matter', 'Geld spielt keine Rolle.']]),
    examples: [{ de: 'Kannst du mir Bescheid sagen, wenn du ankommst?', en: 'Can you let me know when you arrive?' }, { de: 'Ich möchte eine Frage stellen.', en: 'I would like to ask a question.' }, { de: 'Das neue Gesetz tritt im Januar in Kraft.', en: 'The new law comes into force in January.' }],
    bank: [
      { p: 'Wir müssen heute eine Entscheidung ___.', en: 'We have to make a decision today.', o: ['treffen', 'machen', 'geben', 'nehmen'], exp: 'eine Entscheidung treffen.' },
      { p: 'Darf ich eine Frage ___?', en: 'May I ask a question?', o: ['stellen', 'machen', 'fragen', 'geben'], exp: 'eine Frage stellen.' },
      { p: 'Sag mir bitte ___, wenn du Zeit hast.', en: 'Please let me know when you have time.', o: ['Bescheid', 'Antwort', 'Information', 'Sicherheit'], exp: 'Bescheid sagen = let someone know.' },
      { p: 'Der Konferenzraum ___ Ihnen den ganzen Tag zur Verfügung.', en: 'The conference room is available to you all day.', o: ['steht', 'ist', 'liegt', 'kommt'], exp: 'zur Verfügung stehen.' },
      { p: 'Ich habe beim Amt einen Antrag ___.', en: 'I submitted an application at the office.', o: ['gestellt', 'gemacht', 'gegeben', 'geschrieben'], exp: 'einen Antrag stellen.' },
      { p: 'Ein Umzug nach Hamburg kommt für uns nicht in ___.', en: 'Moving to Hamburg is not an option for us.', o: ['Frage', 'Kraft', 'Rolle', 'Ordnung'], exp: 'in Frage kommen.' },
      { p: 'Das Alter ___ bei uns keine Rolle.', en: 'Age doesn\'t matter to us.', o: ['spielt', 'macht', 'hat', 'gibt'], exp: 'eine Rolle spielen.' }] },
  ];
})();
